43	  }
44	
45	  const nextLineStart = lineStarts[lineNumber + 1];
46	  const endOffset = nextLineStart === undefined ? markdown.length : nextLineStart - 1;
47	  return {
48	    text: markdown.slice(startOffset, endOffset),
